import { ChevronDown, ChevronRight } from 'lucide-react';
import type { Ref } from 'react';
import { conversationListStyles as s } from './conversationList.variants';
import type { ConversationSummary } from './types';

export type ConversationEntry =
  | { kind: 'group'; key: string; groupKey: string; label: string; collapsed: boolean }
  | { kind: 'row'; key: string; item: ConversationSummary };

export function ConversationGroup({
  entry,
  tabIndex,
  onToggle,
  onFocus,
  controlRef,
}: {
  entry: Extract<ConversationEntry, { kind: 'group' }>;
  tabIndex: number;
  onToggle: () => void;
  onFocus: () => void;
  controlRef: Ref<HTMLButtonElement>;
}) {
  const Chevron = entry.collapsed ? ChevronRight : ChevronDown;
  return (
    <h3>
      <button
        ref={controlRef}
        type="button"
        data-conversation-key={entry.key}
        tabIndex={tabIndex}
        className={s.heading}
        aria-expanded={!entry.collapsed}
        onClick={onToggle}
        onFocus={onFocus}
      >
        <Chevron size={14} aria-hidden className={entry.collapsed ? 'shrink-0 rtl:rotate-180' : 'shrink-0'} />
        {entry.label}
      </button>
    </h3>
  );
}

import { Button, Kbd, cn } from '@gntik-ai/ui';
import { useLayoutEffect, useRef, useState } from 'react';
import { useChatI18n } from '../utils/i18n';
import { ConversationGroup, type ConversationEntry } from './ConversationGroup';
import { ConversationRow } from './ConversationRow';
import { conversationGroups, type RecencyKey } from './groupByRecency';
import { useConversationWindow } from './useConversationWindow';
import { navigationTarget } from './keyboard';
import { conversationListStyles as s } from './conversationList.variants';
import type { ConversationListProps } from './types';

export function ConversationList({
  items,
  activeId,
  defaultActiveId = null,
  onActiveChange,
  virtualizeAt = 100,
  onNew,
  newShortcut,
  hasMore,
  loadingMore,
  onLoadMore,
  getHref,
  onRename,
  onDelete,
  itemActions,
  label,
  emptyState,
  groupBy = 'recency',
  now = new Date(),
  className,
  collapsedGroups,
  defaultCollapsedGroups = [],
  onCollapsedGroupsChange,
}: ConversationListProps) {
  const { tc } = useChatI18n();
  const [innerActive, setInnerActive] = useState(defaultActiveId);
  const active = activeId === undefined ? innerActive : activeId;
  const [innerCollapsed, setInnerCollapsed] = useState(defaultCollapsedGroups);
  const collapsed = collapsedGroups ?? innerCollapsed;
  const toggle = (key: string) => {
    const next = collapsed.includes(key) ? collapsed.filter((value) => value !== key) : [...collapsed, key];
    if (collapsedGroups === undefined) setInnerCollapsed(next);
    onCollapsedGroupsChange?.(next);
  };
  const entries: ConversationEntry[] = conversationGroups(items, groupBy, now).flatMap((group) => {
    const rows: ConversationEntry[] = group.items.map((item) => ({ kind: 'row', key: `row:${item.id}`, item }));
    if (groupBy === false) return rows;
    const heading: ConversationEntry = {
      kind: 'group',
      key: `group:${group.key}`,
      groupKey: group.key,
      label: groupBy === 'recency' ? tc(`chat.${group.key as RecencyKey}`) : group.key,
      collapsed: collapsed.includes(group.key),
    };
    return [heading, ...(heading.collapsed ? [] : rows)];
  });
  const enabled = entries.filter((entry) => entry.kind === 'group' || !entry.item.disabled);
  const initial =
    enabled.find((entry) => entry.kind === 'row' && entry.item.id === active) ??
    enabled.find((entry) => entry.kind === 'row') ??
    enabled[0];
  const [focused, setFocused] = useState<{ key: string; active: string | null } | null>(null);
  const tabKey =
    focused?.active === active && enabled.some((entry) => entry.key === focused.key) ? focused.key : initial?.key;
  const virtual = items.length > virtualizeAt;
  const { indices, win, setViewport, setScrollTop, measure, reveal } = useConversationWindow(entries, tabKey, virtual);
  const controls = useRef(new Map<string, HTMLElement>());
  const pendingFocus = useRef(false);
  useLayoutEffect(() => {
    if (pendingFocus.current && tabKey) {
      controls.current.get(tabKey)?.focus({ preventScroll: virtual });
      pendingFocus.current = false;
    }
  });
  const register = (key: string, node: HTMLElement | null) => {
    if (node) controls.current.set(key, node);
    else controls.current.delete(key);
  };
  return (
    <div className={cn(s.root, className)}>
      {onNew && (
        <Button variant="secondary" className="mx-2 shrink-0" onClick={onNew}>
          {tc('chat.newChat')}
          {newShortcut && <Kbd>{newShortcut}</Kbd>}
        </Button>
      )}
      <nav
        ref={setViewport}
        onScroll={(event) => setScrollTop(event.currentTarget.scrollTop)}
        aria-label={label ?? tc('chat.conversations')}
        className={s.nav}
        onKeyDown={(event) => {
          const current = (event.target as HTMLElement).dataset.conversationKey;
          if (!current) return;
          const key = navigationTarget(event.key, current, entries);
          if (key) {
            event.preventDefault();
            pendingFocus.current = true;
            reveal(key);
            setFocused({ key, active });
          }
        }}
      >
        <div className="relative" style={virtual ? { height: win.total } : undefined}>
          {indices.map((index) => {
            const entry = entries[index]!;
            return (
              <div
                key={entry.key}
                ref={(node) => measure(entry.key, node)}
                className={virtual ? 'absolute inset-x-0 top-0' : undefined}
                style={virtual ? { transform: `translateY(${win.offsets[index] ?? 0}px)` } : undefined}
              >
                {entry.kind === 'group' ? (
                  <ConversationGroup
                    key={entry.key}
                    entry={entry}
                    controlRef={(node) => register(entry.key, node)}
                    tabIndex={entry.key === tabKey ? 0 : -1}
                    onFocus={() => setFocused({ key: entry.key, active })}
                    onToggle={() => toggle(entry.groupKey)}
                  />
                ) : (
                  <ConversationRow
                    key={entry.key}
                    item={entry.item}
                    now={now}
                    onRename={onRename}
                    onDelete={onDelete}
                    itemActions={itemActions}
                    current={entry.item.id === active}
                    controlRef={(node) => register(entry.key, node)}
                    tabIndex={entry.key === tabKey ? 0 : -1}
                    onFocus={() => setFocused({ key: entry.key, active })}
                    href={getHref?.(entry.item)}
                    onActivate={() => {
                      if (activeId === undefined) setInnerActive(entry.item.id);
                      onActiveChange?.(entry.item.id);
                    }}
                  />
                )}
              </div>
            );
          })}
        </div>
        {items.length === 0 && emptyState}
      </nav>
      {hasMore && (
        <Button
          variant="ghost"
          className="mx-2 shrink-0"
          loading={loadingMore}
          onClick={() => {
            if (!loadingMore) onLoadMore?.();
          }}
        >
          {tc('chat.loadMore')}
        </Button>
      )}
    </div>
  );
}

import { Badge, Input, MoreMenu, type MoreMenuAction } from '@gntik-ai/ui';
import { useEffect, useState, useRef, type Ref } from 'react';
import { useChatI18n } from '../utils/i18n';
import { groupByRecency } from './groupByRecency';
import { conversationListStyles as s } from './conversationList.variants';
import type { ConversationListProps, ConversationSummary } from './types';

export interface ConversationRowProps {
  item: ConversationSummary;
  now: Date;
  current: boolean;
  tabIndex: number;
  href?: string;
  controlRef: Ref<HTMLButtonElement | HTMLAnchorElement>;
  onFocus: () => void;
  onActivate: () => void;
  onRename?: ConversationListProps['onRename'];
  onDelete?: ConversationListProps['onDelete'];
  itemActions?: ConversationListProps['itemActions'];
}

export function ConversationRow({
  item,
  now,
  current,
  tabIndex,
  href,
  controlRef,
  onFocus,
  onActivate,
  onRename,
  onDelete,
  itemActions,
}: ConversationRowProps) {
  const { formatDate, tc, t, dir } = useChatI18n();
  const root = useRef<HTMLDivElement>(null);
  const actions = useRef<HTMLButtonElement | null>(null);
  const focusRow = () => root.current?.querySelector<HTMLElement>('[data-conversation-key]')?.focus();
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(item.title);
  const input = useRef<HTMLInputElement>(null);
  const restoreFocus = useRef(false);
  useEffect(() => {
    if (!editing && !restoreFocus.current) return;
    const frame = requestAnimationFrame(() => {
      if (editing) {
        input.current?.focus();
        input.current?.select();
      } else {
        root.current?.querySelector<HTMLElement>('[data-conversation-key]')?.focus();
        restoreFocus.current = false;
      }
    });
    return () => cancelAnimationFrame(frame);
  }, [editing]);
  const startRename = () => {
    if (!item.disabled && onRename) {
      setDraft(item.title);
      setEditing(true);
    }
  };
  const finishRename = (save: boolean) => {
    const title = draft.trim();
    if (save && title && title !== item.title) onRename?.(item.id, title);
    restoreFocus.current = true;
    setEditing(false);
  };
  const menu: MoreMenuAction[] = [
    ...(onRename ? [{ label: tc('chat.rename'), onSelect: startRename }] : []),
    ...(onDelete ? [{ label: t('common.delete'), destructive: true, onSelect: () => onDelete(item.id) }] : []),
    ...(itemActions?.(item) ?? []),
  ];
  const title = editing ? (
    <Input
      ref={input}
      aria-label={tc('chat.rename')}
      size="sm"
      value={draft}
      onValueChange={setDraft}
      onBlur={() => setEditing(false)}
      onKeyDown={(event) => {
        event.stopPropagation();
        if (event.nativeEvent.isComposing) return;
        if (event.key === 'Enter' || event.key === 'Escape') {
          event.preventDefault();
          finishRename(event.key === 'Enter');
        }
      }}
    />
  ) : (
    item.title
  );
  const contents = (
    <>
      {item.icon}
      <span className="min-w-0 flex-1">
        <span className="flex items-baseline gap-2">
          <span className={s.title}>{title}</span>
        </span>{' '}
        {item.preview && <span className="mt-0.5 block truncate text-xs text-muted-foreground">{item.preview}</span>}
      </span>{' '}
      {(item.unread ?? 0) > 0 && (
        <Badge tone="primary" size="sm" aria-label={tc('chat.unreadCount', { count: item.unread ?? 0 })}>
          {item.unread}
        </Badge>
      )}{' '}
      <time
        className="shrink-0 whitespace-nowrap text-[11px] text-muted-foreground"
        dateTime={new Date(item.updatedAt).toISOString()}
      >
        {formatDate(
          item.updatedAt,
          groupByRecency(item.updatedAt, now) === 'today' ? { timeStyle: 'short' } : { dateStyle: 'short' },
        )}
      </time>
    </>
  );
  const props = {
    'data-conversation-key': `row:${item.id}`,
    'aria-current': current ? ('true' as const) : undefined,
    'aria-disabled': item.disabled || undefined,
    tabIndex,
    className: s.row,
    onFocus,
    onClick: (event: React.MouseEvent) => {
      if (item.disabled) event.preventDefault();
      else onActivate();
    },
  };
  const row = editing ? (
    <div className={s.row}>{contents}</div>
  ) : href !== undefined ? (
    <a
      {...props}
      ref={controlRef as Ref<HTMLAnchorElement>}
      href={href}
      onKeyDown={(event) => {
        if (event.key === ' ') {
          event.preventDefault();
          if (!item.disabled) event.currentTarget.click();
        }
      }}
    >
      {contents}
    </a>
  ) : (
    <button {...props} ref={controlRef as Ref<HTMLButtonElement>} type="button" disabled={item.disabled}>
      {contents}
    </button>
  );
  return (
    <div
      className="group flex items-center gap-1"
      ref={(node) => {
        root.current = node;
        actions.current = node?.querySelector<HTMLButtonElement>('button[aria-haspopup="menu"]') ?? null;
        if (actions.current) {
          actions.current.tabIndex = -1;
          actions.current.disabled = !!item.disabled;
        }
      }}
      onFocus={(event) => {
        if (actions.current?.isSameNode(event.target)) onFocus();
      }}
      onKeyDown={(event) => {
        if (item.disabled) return;
        if (event.target === actions.current) {
          if (event.key === 'Escape' || event.key === (dir === 'rtl' ? 'ArrowRight' : 'ArrowLeft')) {
            event.preventDefault();
            event.stopPropagation();
            focusRow();
          }
        } else if ((event.target as HTMLElement).dataset.conversationKey) {
          if (event.key === (dir === 'rtl' ? 'ArrowLeft' : 'ArrowRight')) {
            event.preventDefault();
            actions.current?.focus();
          } else if (event.key === 'F2' && onRename) {
            event.preventDefault();
            startRename();
          }
        }
      }}
    >
      {row}
      <MoreMenu
        label={tc('chat.conversationActions', { title: item.title })}
        items={menu}
        variant="ghost"
        size="sm"
        className="shrink-0 opacity-100 group-hover:opacity-100 group-focus-within:opacity-100 [@media(hover:hover)]:opacity-0"
      />
    </div>
  );
}

import { focusRing } from '../utils/focus';

export const conversationListStyles = {
  root: 'flex h-full min-h-0 flex-col gap-2 text-foreground',
  nav: 'min-h-0 flex-1 overflow-y-auto overscroll-contain p-2',
  heading: `flex w-full items-center gap-2 rounded-md px-3 py-2 text-start text-xs font-medium text-muted-foreground ${focusRing}`,
  row: `flex w-full min-w-0 items-start gap-3 rounded-lg px-3 py-2.5 text-start text-[13px] hover:bg-accent/55 aria-[current=true]:bg-accent disabled:opacity-50 aria-disabled:opacity-50 forced-colors:aria-[current=true]:bg-[Highlight] forced-colors:aria-[current=true]:text-[HighlightText] forced-colors:aria-[current=true]:[&_*]:text-[HighlightText] ${focusRing}`,
  title: 'min-w-0 flex-1 truncate text-foreground',
} as const;

import type { ConversationGrouping, ConversationSummary } from './types';

export type RecencyKey = 'today' | 'yesterday' | 'previous7Days' | 'older';
const ORDER: RecencyKey[] = ['today', 'yesterday', 'previous7Days', 'older'];

// Calendar dates, rather than elapsed milliseconds, keep midnight and DST boundaries local.
const calendarDay = (date: Date) => Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()) / 86_400_000;

export function groupByRecency(value: ConversationSummary['updatedAt'], now: Date): RecencyKey {
  const days = calendarDay(now) - calendarDay(new Date(value));
  if (days <= 0) return 'today';
  if (days === 1) return 'yesterday';
  return days < 7 ? 'previous7Days' : 'older';
}

export function conversationGroups(items: ConversationSummary[], groupBy: ConversationGrouping, now: Date) {
  const groups = new Map<string, ConversationSummary[]>();
  for (const item of items) {
    const key =
      groupBy === false ? '' : typeof groupBy === 'function' ? groupBy(item) : groupByRecency(item.updatedAt, now);
    const group = groups.get(key);
    if (group) group.push(item);
    else groups.set(key, [item]);
  }
  const keys = groupBy === 'recency' ? ORDER.filter((key) => groups.has(key)) : [...groups.keys()];
  return keys.map((key) => ({ key, items: groups.get(key) ?? [] }));
}

export { ConversationList } from './ConversationList';
export type { ConversationListProps, ConversationSummary, ConversationGrouping } from './types';
export { doc as conversationListDoc } from './ConversationList.doc';

import type { ConversationEntry } from './ConversationGroup';

export function navigationTarget(key: string, current: string, entries: ConversationEntry[]): string | undefined {
  const enabled = entries.filter((entry) => entry.kind === 'group' || !entry.item.disabled);
  const index = enabled.findIndex((entry) => entry.key === current);
  if (key === 'Home') return enabled[0]?.key;
  if (key === 'End') return enabled.at(-1)?.key;
  if (key === 'ArrowDown') return enabled[Math.min(index + 1, enabled.length - 1)]?.key;
  if (key === 'ArrowUp') return enabled[Math.max(index - 1, 0)]?.key;
}

import type { MoreMenuAction } from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface ConversationSummary {
  id: string;
  title: string;
  preview?: string;
  updatedAt: Date | string | number;
  unread?: number;
  icon?: ReactNode;
  disabled?: boolean;
}

export type ConversationGrouping = 'recency' | false | ((item: ConversationSummary) => string);

export interface ConversationListProps {
  items: ConversationSummary[];
  activeId?: string | null;
  defaultActiveId?: string | null;
  onActiveChange?: (id: string) => void;
  onRename?: (id: string, title: string) => void;
  onDelete?: (id: string) => void;
  itemActions?: (item: ConversationSummary) => MoreMenuAction[];
  getHref?: (item: ConversationSummary) => string;
  collapsedGroups?: string[];
  defaultCollapsedGroups?: string[];
  onCollapsedGroupsChange?: (keys: string[]) => void;
  onNew?: () => void;
  /** Display hint only; the application owns shortcut binding. */
  newShortcut?: string;
  hasMore?: boolean;
  loadingMore?: boolean;
  onLoadMore?: () => void;
  /** Window histories larger than this count; Infinity disables windowing. */
  virtualizeAt?: number;
  label?: string;
  emptyState?: ReactNode;
  groupBy?: ConversationGrouping;
  /** Local clock used for grouping; supply a stable value for SSR. */
  now?: Date;
  className?: string;
}

import { useVirtualWindow } from '@gntik-ai/ui';
import { useCallback, useRef, useState } from 'react';
import type { ConversationEntry } from './ConversationGroup';

/** The virtual-window primitive does no measuring: retain sizes by stable row/group key here. */
export function useConversationWindow(entries: ConversationEntry[], tabKey: string | undefined, virtual: boolean) {
  const viewport = useRef<HTMLElement | null>(null);
  const [height, setHeight] = useState(600);
  const [scrollTop, setScrollTop] = useState(0);
  const [sizes, setSizes] = useState<ReadonlyMap<string, number>>(() => new Map());
  const sizeOf = useCallback(
    (index: number) => {
      const entry = entries[index];
      return entry ? (sizes.get(entry.key) ?? (entry.kind === 'group' ? 32 : entry.item.preview ? 64 : 44)) : 44;
    },
    [entries, sizes],
  );
  const win = useVirtualWindow(entries.length, sizeOf, scrollTop, height, 4);
  const setViewport = useCallback((node: HTMLElement | null) => {
    viewport.current = node;
    if (!node) return;
    if (node.clientHeight > 0) setHeight(node.clientHeight);
    if (typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(() => {
      if (node.clientHeight > 0) setHeight(node.clientHeight);
    });
    observer.observe(node);
    return () => observer.disconnect();
  }, []);
  const measure = useCallback((key: string, node: HTMLElement | null) => {
    if (!node) return;
    const update = () => {
      const nextHeight = Math.ceil(node.getBoundingClientRect().height);
      if (nextHeight > 0)
        setSizes((previous) => {
          if (previous.get(key) === nextHeight) return previous;
          const next = new Map(previous);
          next.set(key, nextHeight);
          return next;
        });
    };
    update();
    if (typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(update);
    observer.observe(node);
    return () => observer.disconnect();
  }, []);
  const indices = virtual
    ? Array.from({ length: Math.max(0, win.end - win.start + 1) }, (_, i) => win.start + i)
    : entries.map((_, i) => i);
  const pinnedIndex = entries.findIndex((entry) => entry.key === tabKey);
  if (virtual && pinnedIndex >= 0 && !indices.includes(pinnedIndex)) indices.push(pinnedIndex);
  indices.sort((a, b) => a - b);
  const reveal = (key: string) => {
    if (!virtual || !viewport.current) return;
    const index = entries.findIndex((entry) => entry.key === key);
    if (index < 0) return;
    const top = win.offsets[index] ?? 0;
    const bottom = win.offsets[index + 1] ?? top;
    const currentTop = viewport.current.scrollTop;
    const next = top < currentTop ? top : bottom > currentTop + height ? bottom - height : currentTop;
    viewport.current.scrollTop = next;
    setScrollTop(next);
  };
  return { indices, win, setViewport, setScrollTop, measure, reveal };
}
